INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('semis', 'CHIPS', 'How many dollars of semiconductors were sold worldwide in 2025?', 'US dollars', 795600000000, NULL, 'Roughly 1.2 trillion chips a year at about 70 cents each is on the order of $800 billion, and AI demand pushed 2025 well above 2024.', 'WSTS reports $795.6 billion, up 26.2%. The Semiconductor Industry Association''s earlier February 2026 release said $791.7 billion before Q4 data was final.', 'WSTS, Global Semiconductor Market grows 26% in 2025', 'https://www.wsts.org/76/103/Global-Semiconductor-Market-grows-26-in-2025-to-796B', '2025 full year, final WSTS data (March 2026)', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('visatx', 'MARKETS', 'How many transactions did Visa process on its networks in its 2025 fiscal year?', 'transactions', 257500000000, 'visa', 'Billions of cards doing a few purchases a week add up to hundreds of billions a year.', 'Visa counts payments and cash transactions on Visa-branded cards, plus Interlink and PLUS. Fiscal 2025 ended September 30, 2025.', 'Visa fiscal 2025 annual report', 'https://s29.q4cdn.com/385744025/files/doc_downloads/2025/Visa-Fiscal-2025-Annual-Report.pdf', 'Fiscal 2025 (to September 2025)', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('visavol', 'MARKETS', 'What was the total payments volume across Visa''s network in its 2025 fiscal year?', 'US dollars', 16700000000000, 'visa', 'About 257 billion transactions at an average of roughly $65 each is close to $17 trillion.', 'Visa reports $16.7 trillion total volume. Its narrower payments-volume measure, which excludes cash, was $14.2 trillion.', 'Visa fiscal 2025 annual report', 'https://s29.q4cdn.com/385744025/files/doc_downloads/2025/Visa-Fiscal-2025-Annual-Report.pdf', 'Fiscal 2025 (to September 2025)', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('tesla', 'MARKETS', 'How many vehicles did Tesla deliver in 2025?', 'vehicles', 1636129, NULL, 'Tesla delivered about 1.8 million in 2024 and sales fell in 2025, so somewhere around 1.6 million.', 'Down 8.6% from 1,789,226 in 2024, after the US federal EV tax credit ended on September 30, 2025. This figure comes from secondary coverage of Tesla''s own release.', 'Not a Tesla App, Tesla Q4 2025 report', 'https://www.notateslaapp.com/news/3468/tesla-reports-q4-delivery-numbers-narrowly-misses-on-deliveries-energy-hits-record', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('phones', 'TECH', 'How many smartphones were shipped worldwide in 2025?', 'smartphones', 1260000000, NULL, 'About 6 billion people use a phone, replaced roughly every four years, which is nearly 1.3 billion a year.', 'IDC''s preliminary January 2026 figure is 1.26 billion, up about 2%. Omdia reported 1.25 billion.', 'IDC smartphone tracker, January 2026', 'https://www.idc.com/?p=107472', '2025 full year, preliminary', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('metadap', 'TECH', 'How many people used at least one Meta app (Facebook, Instagram, WhatsApp or Messenger) on an average day in June 2026?', 'daily active people', 3600000000, 'meta', 'Facebook alone has about 2 billion daily users, and Instagram and WhatsApp add many who do not use Facebook.', 'Meta calls this metric family daily active people and reports it as a monthly average. It was up 3% on a year earlier.', 'Meta Q2 2026 results', 'https://investor.atmeta.com/investor-news/press-release-details/2026/Meta-Reports-Second-Quarter-2026-Results/', 'June 2026 average', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('instagram', 'TECH', 'How many people use Instagram every day?', 'daily users', 2000000000, 'meta', 'Instagram has about 3 billion monthly users and around two-thirds use it daily.', 'Meta said Instagram reached 2 billion daily users during the second quarter of 2026. This comes from reporting on the results call, so check the transcript for the exact wording.', 'Meta Q2 2026 results', 'https://investor.atmeta.com/investor-news/press-release-details/2026/Meta-Reports-Second-Quarter-2026-Results/', 'Q2 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('whatsapp', 'TECH', 'How many people use WhatsApp every month?', 'monthly users', 3000000000, 'meta', 'It leads messaging in India, Brazil and Europe, so well over a third of humanity.', 'Mark Zuckerberg said WhatsApp passed 3 billion monthly users on the April 30, 2025 earnings call. The real number today is probably higher, so consider replacing this with a newer figure.', 'Canaltech, reporting Meta''s Q1 2025 call', 'https://canaltech.com.br/mercado/whatsapp-tem-mais-de-3-bilhoes-de-usuarios-mensais-revela-meta/', 'April 2025', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('domains', 'TECH', 'How many domain names were registered across all extensions worldwide at the end of June 2026?', 'domain names', 401600000, NULL, 'About 170 million are .com, and .com is roughly 40 to 45% of all registrations, which gives around 400 million.', 'Verisign''s Domain Name Industry Brief reports 401.6 million, up 8.1% on a year earlier. .com and .net together were about 179.1 million.', 'Verisign Q2 2026 Domain Name Industry Brief', 'https://blog.verisign.com/domain-names/q2-2026-domain-name-industry-brief-quarterly-report/', 'June 30, 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('starlink', 'TECH', 'How many Starlink satellites are active in orbit?', 'satellites', 10838, NULL, 'SpaceX launches about 25 satellites per Falcon 9 and flies one every few days, so a few thousand a year, on top of the 10,000 reached in March 2026.', 'KeepTrack, a third-party tracker, counted 11,131 in orbit and 10,838 active in October 2026. Its catalog lags recent launches, so the true number is higher. This is not an official SpaceX figure.', 'KeepTrack, Starlink satellite count', 'https://keeptrack.space/starlink-satellite-count', 'October 2026, KeepTrack', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('hashrate', 'CRYPTO', 'What was the Bitcoin network''s average hashrate over the 30 days to the end of August 2026?', 'exahashes per second', 912, NULL, 'It passed 1,000 EH/s in January 2026 and has been in the high hundreds since.', 'Hashrate Index gives a 30-day average of 912 EH/s and a 7-day average of 915 EH/s at August 31, 2026. Hashrate is estimated, not measured directly, so sources differ. One estimate for August 26 was about 860.', 'Hashrate Index roundup, August 31, 2026', 'https://hashrateindex.com/blog/hashrate-index-roundup-august-17-2026-2/', '30 days to August 31, 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('btcsupply', 'CRYPTO', 'How many bitcoin have been mined so far?', 'bitcoin', 20080000, NULL, 'The cap is 21 million, and about 95% of it was issued by the time of the last halving cycle, so about 20 million.', 'Mined supply passed 20 million in March 2026. About 450 new bitcoin are issued a day, so this number rises slowly. Estimates of coins permanently lost run from 3 to 4 million.', 'Mudrex Learn, citing August 2026 data', 'https://mudrex.com/learn/?p=88362', 'August 31, 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('nvrev', 'CHIPS', 'How much revenue did Nvidia report for its 2026 fiscal year, which ended in January 2026?', 'US dollars', 215900000000, 'nvidia', 'Nvidia made about $130 billion the year before and AI demand kept growing at 60% or more.', 'Up 65% from the previous year. Nvidia''s fiscal 2026 ended on January 25, 2026.', 'Nvidia Q4 and fiscal 2026 results (SEC 8-K)', 'https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm', 'Fiscal 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('nvdc', 'CHIPS', 'How much of Nvidia''s fiscal 2026 revenue came from its Data Center segment?', 'US dollars', 193700000000, 'nvidia', 'Gaming and other businesses are a small slice now, so most of the roughly $216 billion total is data center.', 'Up 68%. That is about 90% of Nvidia''s total revenue of $215.9 billion.', 'Nvidia Q4 and fiscal 2026 results (SEC 8-K)', 'https://www.sec.gov/Archives/edgar/data/1045810/000104581026000019/q4fy26pr.htm', 'Fiscal 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('tsmcrev', 'CHIPS', 'How much revenue did TSMC report for 2025?', 'US dollars', 122420000000, NULL, 'TSMC made about $90 billion in 2024 and grew by roughly a third.', 'NT$3.81 trillion, up 31.6% in Taiwan dollars and 35.9% in US dollars. This figure comes from secondary coverage of TSMC''s results, so check TSMC''s own release.', 'TelecomLead, TSMC 2025 results', 'https://telecomlead.com/semiconductor/tsmc-delivers-record-2025-revenue-and-profit-as-ai-chip-demand-fuels-growth-us-expansion-accelerates-124150', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('dram', 'CHIPS', 'How many dollars of DRAM memory chips did the world''s makers sell in the third quarter of 2025?', 'US dollars', 41400000000, NULL, 'Memory is roughly a quarter of the chip market, and DRAM about two-thirds of that, so tens of billions a quarter.', 'TrendForce reported $41.4 billion, up 30.9% from the second quarter. SK hynix led with $13.75 billion and Samsung followed with $13.5 billion.', 'Evertiq, citing TrendForce', 'https://evertiq.com/design/2025-11-26-global-dram-revenue-jumps-309-in-3q25', 'Q3 2025', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('asml', 'CHIPS', 'How many euros of net sales did ASML report for 2025?', 'euros', 32700000000, NULL, 'ASML sold about 300 systems at an average of around €100 million, including EUV machines at far more.', 'A record, with net income of about €9.6 billion. EUV systems were about €11.6 billion of it.', 'eeNews Europe, ASML 2025 results', 'https://www.eenewseurope.com/en/asml-reports-e32-7bn-sales-e9-6bn-net-income-for-2025/', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('chatgpt', 'TECH', 'How many people used ChatGPT every week in February 2026?', 'weekly active users', 900000000, NULL, 'It had 800 million in October 2025 and was adding tens of millions every couple of months.', 'OpenAI announced 900 million weekly users and 50 million paying subscribers on February 27, 2026. A newer figure may exist.', 'TechCrunch, ChatGPT reaches 900M weekly active users', 'https://techcrunch.com/2026/02/27/chatgpt-reaches-900m-weekly-active-users', 'February 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('spotify', 'TECH', 'How many people used Spotify every month in the second quarter of 2026?', 'monthly active users', 777000000, NULL, 'It had around 700 million a year or so earlier and grows by about 10% a year.', 'Up 12% on a year earlier. 300 million of them were Premium subscribers, and 494 million used the ad-supported tier.', 'Spotify Q2 2026 results (SEC 6-K)', 'https://www.sec.gov/Archives/edgar/data/0001639920/000114036126031044/ef20078867_ex99-1.htm', 'Q2 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('netflix', 'TECH', 'How many paid memberships did Netflix have at the end of 2025?', 'paid memberships', 325000000, NULL, 'It passed 300 million at the end of 2024 and added about 20 million a quarter at its best.', 'Netflix said more than 325 million, up from just over 301 million a year earlier. It no longer reports subscribers every quarter, so the exact figure is not public.', 'Netflix FY2025 filing and shareholder letter', 'https://www.sec.gov/Archives/edgar/data/1065280/000106528026000034/nflx-20251231.htm', 'End of 2025', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('wikien', 'TECH', 'How many articles does the English Wikipedia have?', 'articles', 7250000, NULL, 'It passed 7 million in May 2025 and grows by roughly 150,000 to 200,000 a year.', 'The count on the English Wikipedia page was 7,250,570 when checked. It changes daily, so update it from Wikipedia:Statistics shortly before publishing.', 'English Wikipedia', 'https://en.wikipedia.org/wiki/English_Wikipedia', 'October 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('hfmodels', 'CODE', 'How many public models are hosted on the Hugging Face Hub?', 'models', 3012377, NULL, 'It had about 2.4 million in January 2026 and has been adding over a million a year.', 'One third-party tally counts 3,012,377 on August 22, 2026, and Hugging Face''s own summer 2026 report says about 2.96 million. The count is live and grows daily.', 'Voxbooster Hugging Face statistics 2026 (third-party tally)', 'https://voxbooster.com/blog/hugging-face-model-downloads-statistics-2026/', 'August 2026', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('ipos', 'MARKETS', 'How many companies went public on US stock exchanges in 2025?', 'IPOs', 202, NULL, 'A normal year has 150 to 250 sizeable IPOs and 2025 was a recovery year.', 'Renaissance Capital counts 202 IPOs raising $44.0 billion. It excludes SPACs, closed-end funds and companies below a $50 million market cap, and other counts including SPACs reach 354.', 'Renaissance Capital, 2025 US IPO Review', 'https://www.renaissancecapital.com/review/2025USReview_Public.pdf', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('etfs', 'MARKETS', 'How many exchange-traded funds were there in the United States at the end of 2025?', 'ETFs', 4813, NULL, 'The US passed 4,000 ETFs in 2024 and new launches keep coming, so about 4,500 to 5,000.', 'The ICI 2026 Fact Book says 4,813 including ETFs that invest in other ETFs. An ICI FAQ page gives 4,495 for US-domiciled ETFs, so the definition matters.', 'ICI 2026 Fact Book, chapter 2', 'https://icifactbook.org/pdf/2026-factbook-ch2.pdf', 'End of 2025', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('vc', 'MARKETS', 'How many dollars of venture and growth funding did startups raise worldwide in 2025?', 'US dollars', 425000000000, NULL, 'Around 2,000 deals a month averaging ten to fifteen million each, with a few huge AI rounds on top.', 'Crunchbase says about $425 billion, with $211 billion going to AI companies. CB Insights says $469 billion and PitchBook and KPMG say over $512 billion, so every tracker differs. The Crunchbase figure here is relayed by secondary sources.', 'Crunchbase News, 2025 year-end funding', 'https://news.crunchbase.com/fintech/funding-jumped-big-checks-ai-ye-2025/', '2025 full year, Crunchbase', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('applerev', 'MARKETS', 'How much did Apple make in total net sales in its 2025 fiscal year?', 'US dollars', 416161000000, NULL, 'iPhones are about half of Apple''s sales, and 247 million iPhones at about $850 each is roughly $210 billion, so the total is about double that.', 'Fiscal 2025 ended September 27, 2025. iPhone was $209.6 billion and Services $109.2 billion. Up 6.4% on the year before.', 'Apple Form 10-K, fiscal 2025', 'https://www.sec.gov/Archives/edgar/data/320193/000032019325000079/aapl-20250927.htm', 'Fiscal 2025', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('aws', 'TECH', 'How much revenue did Amazon Web Services bring in during 2025?', 'US dollars', 128700000000, 'amazon', 'About $35 billion a quarter by the end of the year and less earlier, so roughly $125 to $130 billion.', 'Up 20% on 2024, with operating income of $45.6 billion. Q4 alone was $35.6 billion.', 'Amazon Q4 2025 results', 'https://www.businesswire.com/news/home/20260204777163/en/Amazon.com-Announces-Fourth-Quarter-Results', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('amazon', 'MARKETS', 'What were Amazon''s total net sales in 2025?', 'US dollars', 716900000000, 'amazon', 'It was around $640 billion in 2024 and grew by about 12%.', 'Up 12% on 2024. AWS made up $128.7 billion of it.', 'Amazon Q4 2025 results', 'https://www.businesswire.com/news/home/20260204777163/en/Amazon.com-Announces-Fourth-Quarter-Results', '2025 full year', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('dcpower', 'TECH', 'How much electricity did data centers around the world use in 2025?', 'terawatt-hours', 485, NULL, 'The whole world uses about 30,000 TWh a year, and data centers are in the region of 1.5 to 2% of that.', 'The IEA estimated 416 TWh in 2024 and about 485 TWh in 2025, with 155 TWh for AI-focused sites. An earlier IEA rounding says about 500. These are estimates, relayed by Our World in Data.', 'Our World in Data, citing the IEA', 'https://ourworldindata.org/how-much-energy-do-data-centers-and-artificial-intelligence-use', '2025 estimate', 'draft');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('internet', 'TECH', 'How many people used the internet worldwide in 2025?', 'people', 6000000000, NULL, 'Eight billion people, and about three-quarters are online.', 'The ITU estimates about 6 billion, with 2.2 billion still offline. It revised its 2024 estimate up to 5.8 billion.', 'ITU, Facts and Figures 2025', 'https://www.itu.int/en/mediacentre/Pages/PR-2025-11-17-Facts-and-Figures.aspx', '2025 estimate', 'draft');
